    description: "Você se concentra nas complexidades da magia que o liga ao seu eidolon para estender a duração do seu magia _Impulsionar Eidolon_ ou _Reforçar Eidolon_. Se sua próxima ação for conjurar _Impulsionar Eidolon_ ou _Reforçar Eidolon_, tente um teste de perícia com a habilidade associada à tradição de magia que você ganha com seu eidolon (como Natureza para um eidolon primordial). A CD geralmente é uma CD de dificuldade padrão do seu nível, mas o Mestre pode atribuir uma CD diferente com base nas circunstâncias. O efeito depende do resultado do seu teste.\n\n**Sucesso crítico** A magia dura 4 rodadas.\n\n**Sucesso** A magia dura 3 rodadas.\n\n**Falha** A magia dura 1 rodada, mas você não gasta Pontos de Foco para conjurar esta magia.",
