    description: "Você chama uma pequena estrela para orbitar uma criatura em um halo cintilante antes de disparar para o céu, onde marca a localização aproximada da criatura. O alvo deve tentar uma salvaguarda de Fortitude.\n\n**Sucesso crítico** O alvo não é afetado.\n\n**Sucesso** O alvo fica ofuscado por 1 rodada.\n\n**Falha** O alvo fica ofuscado por 1 rodada. Enquanto a magia persistir, contanto que você possa ver o céu noturno e o alvo esteja visível do mesmo céu noturno, você poderá sentir a direção e a distância aproximadas da criatura sustentando a magia. Isso é suficiente para rastrear a criatura, mas não para identificar seu quadrado exato (por exemplo, para fazer um ataque). Você pode definir um número de estrelas zênites igual ao seu modificador Sabedoria; se você exceder esse número, sua estrela zênite mais antiga será automaticamente dispensada.\n\n**Falha crítica** Como falha, mas o alvo fica cego por 1 rodada.\n\n**Altura (+1)** A duração aumenta em 1 dia.\n\n**Altura (4º)** Você ignora a condição oculta contra alvos marcados por estrela zênite.",
