    summary: "Risca a menção a um nome específico de um ou mais documentos.",
    description: "Você menciona um nome específico em um ou mais documentos. Ao lançar a magia, dê um nome próprio, seja uma criatura, local ou objeto. Qualquer menção a esse nome no documento fica borrada, manchada ou completamente ilegível. Epítetos e referências inequívocas ao nome também são redigidos; por exemplo, redigir o nome da deusa Sarenrae de um livro também removeria as referências ao seu título \"a Flor do Alvorecer\". As tentativas de utilizar este material de referência para Recordar Conhecimento sobre o nome próprio fornecido falham automaticamente.\n\n**Altura (3º)** Em vez de riscar um determinado nome, você pode substituí-lo por um nome diferente de sua escolha. Epítetos e referências são substituídos por outros semelhantes relacionados ao nome substituto. Qualquer pessoa que leia o texto pode tentar uma verificação de Percepção ou Sociedade em seu CD de magia para perceber o texto alterado, embora isso não diga o que o original dizia.\n\n**Altura (4º)** À sua escolha, a duração é ilimitada.",
