    summary: "Aguça os sentidos próximos, mas o que está longe fica turvo e abafado.",
    description: "Você aguça os sentidos de uma criatura, embora objetos mais distantes se tornem nebulosos, indistintos ou silenciados. O alvo ganha +1 de bônus de status em testes de Percepção realizados com qualquer um de seus sentidos precisos. Além disso, quaisquer sentidos imprecisos que o alvo tenha são aguçados para sentidos precisos (embora não recebam o bônus de status). No entanto, o alvo não consegue perceber nada além de um alcance de 6 m com nenhum dos seus sentidos. A duração é determinada pela salvaguarda de Vontade do alvo. Você pode permitir que os aliados escolham o resultado em vez de tentarem uma salvaguarda.\n\n**Sucesso crítico** O alvo não é afetado.\n\n**Sucesso** O alvo é afetado por 1 rodada.\n\n**Falha** O alvo é afetado por 1 minuto.\n\n**Falha crítica** Como falha, mas o alvo não consegue perceber nada além de um alcance de 3 m.\n\n**Altura (3º)** Você pode mirar em até 2 criaturas.\n\n**Altura (6º)** Você pode mirar em até 4 criaturas.",
