    description: "O poder sombrio da sua aparição se mistura com o seu corpo físico, permitindo que você assuma características aterrorizantes de criaturas que se escondem em lugares escuros. Seus braços e pernas se transformam em tentáculos retorcidos. Você ganha um tentáculo ataques desarmados com alcance de 3 m que causa 1d8 dano de concussão e possui a característica agarrar. Na primeira vez que você Sustentar esta magia a cada rodada, você pode tentar um único teste de Agarrar com seu tentáculo contra uma criatura ao seu alcance.\n\n**Altura (2º)** Você pode escolher assumir a forma de batalha de tubarão de _Forma Animal_ em vez de ganhar um tentáculo ataques desarmados, aumentado para o mesmo nível desta magia de navio. Quando você faz isso, esta magia perde a característica metamorfose e ganha a característica polimorfia. Você pode tentar um Golpe desarmado de mandíbulas contra uma criatura ao seu alcance cada vez que Sustentar esta magia.\n\n**Altura (5º)** Você pode escolher assumir a forma de batalha elemental da água de _Forma Elemental_ em vez de ganhar um tentáculo ataques desarmados, aumentado para o mesmo nível desta magia de navio. Quando você faz isso, esta magia perde a característica metamorfose e ganha a característica polimorfia. Você pode tentar ataques desarmados Golpe contra uma criatura ao seu alcance cada vez que Sustentar esta magia.",
