    actionType: "one",
    focus: true,
    summary: "Transforma só uma parte do corpo.",
    description: "Você transforma apenas uma parte do seu corpo. Escolha qualquer efeito que corresponda a um talento de ordem indomável que você possui.\n **Forma Indomada** Suas mãos se transformam em garras incrivelmente afiadas. Garras indomadas são ataques desarmados, possuem traços de agilidade e sutileza e causam 1d6 dano cortante. Você ainda pode segurar e usar itens com as mãos enquanto eles são transformados por esta magia, mas você deve ter uma mão livre para atacar com ela. **Forma de Inseto** Sua boca se transforma em mandíbulas mortais. Mandíbulas indomadas são ataques desarmados que causam 1d8 dano perfurante. **Forma Elemental** Você muda seu corpo para ser parcialmente composto de matéria elemental, garantindo resistência 5 a acertos críticos e dano de precisão. **Forma de planta** Seus braços se transformam em longas trepadeiras, aumentando seu alcance para 3 m (ou 4,5 m com uma arma de alcance). **Soaring Shape** Você deve lançar _Mudança Indomada_ usando 2 ações para este benefício. Você cria asas nas costas, ganhando um Deslocamento de voo de 9 m.\n\n**Altura (6º)** Você pode escolher até dois efeitos da lista. Garras indomadas deixam ferimentos terríveis e irregulares que também causam 2d6 dano persistente de sangramento ao acertar, e mandíbulas indomadas são envenenadas, também causando 2d6 dano persistente de veneno ao acertar.\n\n**Altura (10º)** Você pode escolher até três efeitos da lista. Garras indomadas causam 4d6 dano persistente de sangramento ao acertar, e mandíbulas indomadas causam 4d6 dano persistente de veneno ao acertar.",
