    description: "Você aprendeu a ler o futuro nos padrões de chamas e fumaça. Embora inexatas e muitas vezes simbólicas, essas leituras ajudam a prepará-lo para eventos futuros. Ao Conjurar esta Magia, você deve estar perto de um fogo (de qualquer tamanho) durante todo o período. Após a conclusão, role 1d4 para sua previsão. O benefício dura 10 minutos ou até ser esgotado, o que ocorrer primeiro. Depois de lançar olhar de cinza, você não poderá lançá-lo novamente por 10 minutos. **Perigo Terrível** Você ganha +2 de bônus de status em sua próxima jogada de iniciativa. **Nova Vida** Na próxima vez que você sofrer dano, pouco antes de sofrer o dano, você ganhará 6 PV temporariamente. **Vivid Insight** (fortuna) Na próxima vez que você tentar um teste no Recordar Conhecimento, jogue duas vezes e obtenha o resultado mais alto. **Boa Fortuna** (fortuna) Na próxima vez que você tentar uma salvaguarda, jogue duas vezes e obtenha o melhor resultado.\n\n**Altura (+1)** O número de PV temporários de nova vida aumenta em 2.",
