    description: "Seu toque evoca uma massa agitada de água gelada que se agarra ao seu alvo, causando 1d4 dano de concussão e 1d4 dano de frio. O alvo deve tentar uma salvaguarda de Fortitude.\n\n**Sucesso crítico** O alvo não é afetado.\n\n**Sucesso** O alvo sofre metade do dano e –1,5 m de sorte ocasional às suas velocidades até o fim do seu próximo turno.\n\n**Falha** O alvo sofre dano total e –3 m de variação de circunstâncias em suas velocidades até o fim do seu próximo turno.\n\n**Falha crítica** Como falha, mas o alvo sofre o dobro do dano.\n\n**Altura (+1)** O espancamento e o dano de frio aumentam em 1d4 cada um.",
