    summary: "Infunde atração no alvo, deixando-o mais amistoso com você.",
    description: "Você infunde atração em seu alvo, fazendo com que ele aja de maneira mais amigável com você. O alvo tenta uma salvaguarda de Vontade. Ele ganha +4 de bônus de circunstância neste teste se você ou seus aliados recentemente o ameaçaram ou foram hostis a ele.\n\n**Sucesso crítico** O alvo não é afetado e sabe que você tentou encantá-lo.\n\n**Sucesso** O alvo não é afetado, mas pensa que seu magia foi algo inofensivo em vez de um toque encantador, a menos que identifique a magia (veja Identificando Magias na página 303).\n\n**Falha** A atitude do alvo se torna amigável com você. Se foi amigável, torna-se útil. Não pode usar ações hostis contra você. Se você usar uma ação hostil contra o alvo, a magia termina. Você pode descartar a magia. Depois que a magia termina, o alvo não necessariamente percebe que foi enfeitiçado, a menos que sua amizade com você ou as ações que você o convenceu a tomar entrem em conflito com suas expectativas. Se ele não perceber que você o encantou, você poderá convencê-lo a continuar sendo seu amigo por meios mundanos.\n\n**Falha crítica** Como fracasso, mas o alvo ajuda.",
