    description: "Você brande sua arma sentinela, invocando a imagem de sua constelação acima de sua cabeça. A constelação então libera uma explosão poderosa que causa 2d10 de dano a todos os inimigos em uma linha de 9 m ou cone de 4,5 m, com um salvamento básico contra seu CD de magia arcano. Inimigos que falham criticamente são ofuscados até o início do seu próximo turno. O tipo de dano, características, área e salvaguardas são determinados pela constelação do seu zodíaco (veja abaixo).\n\n##\n\n Ataque Constelação (Área, Salvamento, Tipo de Dano; Características)\n Respiradouros Vulcânicos do Dragão do Submundo (linha, Reflexos, fogo)\n Ogro\n Balanço selvagem (cone, Fortitude, espancamento)\n Espadachim Lâminas de luz caindo (linha, Reflexos,\r\npiercing) Dragão da Floresta\n Enxame de Insetos (cone, Fortitude, veneno)\n Dragão do Mar\n Água do mar pressurizada (linha, Reflexos, piercing; traço água)\n Blossom Storming pétalas e pólen (linha, Fortitude; veneno, planta, madeira)\n Andorinha Rajada de Vento (cone, Reflexos, corte; ar)\n Cachorro Um cachorro mordedor (linha, reflexos, corte)\n Boi\n Um boi pisoteador (linha, reflexos, espancamento)\n Dragão do Céu\n Relâmpago Dracônico (linha, Reflexos, eletricidade)\n Dragão Soberano\n Rugido psíquico (cone, Vontade, mental)\n Arqueiro Granizo de Flechas de Prata (piercing, cone, Reflexos)\n\n**Altura (+1)** O dano aumenta em 1d10.",
