    description: "A madeira se molda prontamente de acordo com sua vontade, fazendo com que escadas apareçam conforme você sobe na lateral de uma árvore, tecendo automaticamente trepadeiras em escadas ou abaixando galhos para levantá-lo até o topo. Ao Conjurar esta Magia, mova-se para o seu Deslocamento em qualquer direção ou ao longo de qualquer superfície, desde que haja plantas vivas ou árvores de tamanho Grande ou maior dentro de 4,5 m de você. A madeira permite que você se mova, mas não protege de terrenos perigosos ou outros perigos. Cada vez que você sustenta esta magia, você pode se mover novamente da mesma maneira.\n\n**Altura (8º)** A duração desta magia passa a ser de 10 minutos. Você não precisa mais Sustentar a magia para estender sua duração, mas pode Sustentá-lo para se mover conforme descrito.",
