    description: "Você dessincroniza magicamente o plano atual de existência, prendendo criaturas em uma área que gira sobre si mesma como um plano ilimitado. Sempre que uma criatura tentar entrar ou sair da área, ela deverá tentar uma salvaguarda de Vontade.\n\n**Sucesso crítico** A criatura entra ou sai da área conforme pretendido.\n\n**Sucesso** A criatura entra ou sai da área com sucesso, mas aparece em um espaço aleatório desocupado adjacente à borda da área.\n\n**Falha** A criatura não consegue entrar ou sair da área, em vez disso aparece em um espaço aleatório e desocupado adjacente à borda da área, e seu movimento termina imediatamente.\n\n**Falha crítica** Como falha, exceto que a criatura não pode tentar entrar ou sair novamente neste turno.",
