    provenance: { type: 'official' },
    actionType: "two",
    focus: true,
    summary: "Multiplica a doença numa criatura, puxando-a para um nevoeiro infeccioso.",
    description: "Você multiplica a doença dentro de uma criatura, atraindo-a para uma névoa infecciosa fora de seu corpo, onde pode se espalhar para outras criaturas. O alvo deve tentar uma salvaguarda de Vontade. Se o alvo estiver disposto, ele poderá optar por sofrer os efeitos de uma falha crítica.\n\n**Sucesso crítico** O alvo recebe o benefício de uma defesa bem-sucedida contra a doença de nível mais baixo que o afeta.\n\n**Sucesso** O alvo não é afetado.\n\n**Falha** Uma doença escolhida aleatoriamente afetando o alvo preenche o ar em uma emanação de 4,5 m centrada no alvo. Durante a duração da magia, qualquer criatura que entre ou termine seu turno dentro da área fica exposta a essa doença.\n\n**Falha crítica** Como falha, exceto que o miasma contém todas as doenças que afetam o alvo.",
