    focus: true,
    summary: "Concede ao alvo vislumbres do que virá, guiando-o a um destino que lhe convém.",
    description: "Você concede ao alvo uma visão sobre o que está por vir, guiando-o em direção a um destino que considere mais adequado e encorajando-o a continuar esta jornada. A criatura rola um d20 no início de cada um de seus turnos. A criatura pode usar o resultado da rolagem em vez de rolar para qualquer teste antes do início do próximo turno. Se a criatura substituir a rolagem dessa maneira, ela ganha +1 de bônus de status em qualquer teste que substituir no turno seguinte. Substituições repetidas aumentam os bônus de status em 1, até um total de +2. Se a criatura começar seu turno sem ter feito nenhuma rolagem na rodada anterior, a magia termina.\n\n**Altura (7º)** O bônus de status pode aumentar até um total de +3.\n\n**Altura (10º)** O bônus de status pode aumentar até um total de +4.",
