    focus: true,
    summary: "Deixa o alvo presunçoso, fazendo-o atribuir falhas a fatores externos.",
    description: "Você deixa o alvo confiante demais, levando-o a atribuir o fracasso a fatores externos. O alvo tenta uma salvaguarda de Vontade para determinar a duração da magia e fica temporariamente imune por 24 horas, independentemente do resultado do salvamento.\n\n**Sucesso crítico** O alvo não é afetado.\n\n**Sucesso** A duração é de 1 rodada. Se o alvo falhar em uma rolagem de ataque ou teste de perícia, ele leva -1 sorte de status para rolagem de ataques e teste de perícias até o final do seu turno (ou o final do seu próximo turno, se ele tentou a rolagem fora do seu turno). Se a criatura falhar uma segunda vez ao cumprir esta penalidade, a penalidade aumenta para –2.\n\n**Falha** Sucesso, mas a duração é de 10 minutos.\n\n**Falha crítica** Sucesso, mas a duração é de 24 horas.",
