    focus: true,
    summary: "Profere uma palavra de poder libertadora que liberta uma criatura.",
    description: "Você pronuncia uma palavra libertadora de poder que liberta uma criatura. Você suprime uma das seguintes condições de sua escolha: confuso, amedrontado, agarrado, paralisado ou imobilizado. O alvo não é afetado pela condição escolhida e se você suprimir a condição agarrado ou imobilizado, o alvo se liberta automaticamente do agarrão ou da restrição quando você lança a magia.\n\n Se você não remover o efeito que forneceu a condição, a condição retornará após o término da magia. Por exemplo, se uma magia deixasse o alvo confuso por 1 minuto, _word of freedom_ deixaria o alvo agir normalmente por uma rodada, mas a condição confusa retornaria depois.",
