    description: "Você super-resfria o ar próximo, formando uma nuvem de cristais de gelo dançantes em uma emanação ao seu redor. Uma criatura diferente de você que entre na área ou termine seu turno dentro da área sofre 2d6 dano de frio. Uma criatura pode sofrer este dano apenas uma vez por turno. Os cristais dispersam e refratam a luz; se um efeito de luz entrar na área do pó de diamante, qualquer criatura alvo desse efeito ganha +2 de bônus de status para CA e salva contra ele. Enquanto a magia persistir, você pode ativar ou desativar esta aura sustentando a magia. Você pode dispensar esta magia.\n\n**Altura (+2)** O dano aumenta em 1d6.",
