    description: "Você aproveita o espírito da época de qualquer assentamento ao seu alcance. Você aprende os nomes dos assentamentos. Em todos os testes de Conhecimento para Recordar Conhecimento sobre esses assentamentos ou para Coletar Informações dentro ou sobre esses assentamentos, você ganha +2 de bônus de status e usa seu nível como bônus de proficiência mesmo se não estiver treinado. Ao lançar a magia, você pode imediatamente registrar conhecimento sobre um dos assentamentos usando sua habilidade Lore (como Absalom Lore), que se beneficia do bônus. Se você lançar _pulse of civilization_ novamente, qualquer lançamento anterior termina.\n\n**Altura (5º)** O alcance é de 100 milhas.\n\n**Altura (7º)** O alcance é de 500 milhas e o bônus é de +3.",
