    summary: "Garante que um segredo continue a salvo de espiões.",
    description: "Você garante que um segredo permaneça protegido contra espiões curiosos. Escolha uma informação que pelo menos alguns dos alvos conheçam, como “a localização do tesouro roubado” ou “a senha para entrar na casa da guilda”. A magia concede àqueles que conhecem o conhecimento que você escolheu um bônus de status de +4 para testes de perícias (normalmente testes de Enganação) para ocultar esse conhecimento, para salvaguardas contra magias que especificamente tentam obter esse conhecimento deles, e para efeitos que os forçariam a revelá-lo.\n\n Se você Conjurar esta Magia novamente, qualquer _Resguardar Segredo_ anterior que você conjurou termina.",
