    description: "Você inscreve uma runa invisível em forma de olho no ar, criando um sensor como _Clarividência_. Quando criado, esse olho deve estar na sua linha de visão.\n\n Cada vez que a duração da magia termina, você pode gastar 1 Ponto de Foco como ação livre para prolongar a duração por mais uma hora, embora normalmente ele termine imediatamente durante seus próximos preparativos diários.",
