    summary: "Cobre a mente do alvo com imagens oníricas, dificultando distinguir ameaças reais.",
    description: "Você obscurece a mente do alvo com imagens vívidas e oníricas, fazendo com que ele tenha dificuldade em distinguir ameaças reais de ameaças imaginárias.\n\n**Sucesso crítico** O alvo não é afetado.\n\n**Sucesso** O alvo é distraído pelas visões e trata todas as outras criaturas como ocultas por 1 rodada, e você não pode Sustentar o Magia para aumentar a duração.\n\n**Falha** O alvo é confuso. Além das criaturas presentes, o alvo também pode atacar descontroladamente no ar, tentando afastar os sonhos. Ele pode tentar um novo salvamento no final de cada um de seus turnos para acabar com a confusão. Mesmo que o efeito de confusão termine mais cedo, o alvo trata todas as outras criaturas como ocultas por 1 rodada.\n\n**Falha crítica** Como falha, mas o alvo não consegue salvar para encerrar o efeito mais cedo.",
