    rank: 4,
    traditions: ["divine"],
    traits: ["Cleric", "Concentrate", "Linguistic", "Manipulate", "Mental", "Focus"],
    rarity: "rare",
    provenance: { type: 'official' },
    focus: true,
    summary: "Invoca brisas que tecem fofocas e sussurram nos ouvidos ao redor. (raro)",
    description: "Você evoca inúmeras brisas nas quais tece fofocas, sussurrando sutilmente nos ouvidos das pessoas ao seu redor. Escolha um boato ou informação que você deseja espalhar, que pode ou não ser verdade, sobre um único assunto. Aqueles dentro do alcance da magia ouvem o boato em algum momento durante a próxima hora, embora não sejam capazes de identificá-lo em uma fonte. Tente um teste com um modificador igual ao seu CD de magia – 10 contra uma CD difícil para o seu nível. O Mestre pode modificar a CD dependendo de quão plausível é o boato. Conjurações repetidas para espalhar o mesmo boato ou informação não terão efeito, a menos que as circunstâncias tenham mudado substancialmente, conforme determinado pelo Mestre.\n\n**Sucesso crítico** Seu boato se espalha por toda parte e está na ponta da língua das pessoas. Durante 1 semana, qualquer um que obtiver sucesso em um teste para Coletar Informações sobre um assunto específico aprende o seu boato em detrimento de outros rumores sobre o assunto. Testes de perícia para convencer as pessoas de que o boato é verdadeiro recebem +2 de bônus de circunstância.\n\n**Sucesso** Muitas pessoas percebem que o boato começa a se espalhar, embora aqueles que ouviram o boato não estejam necessariamente convencidos. Durante 1 semana, qualquer pessoa que obtiver sucesso em um teste para Coletar Informações sobre o assunto específico adiciona seu boato à lista de rumores que poderia aprender sobre o assunto, e teste de perícias para convencer as pessoas de que o boato é verdadeiro recebe +1 bônus de circunstância.\n\n**Falha** A maioria na área descarta o boato como fofoca selvagem e dá pouca atenção a ele, não garantindo nenhum efeito.\n\n**Falha crítica** A fofoca dos ventos é mal interpretada e espalha informações contraditórias ao boato que você estava tentando espalhar. Um boato contraditório se espalha e teste de perícias para convencer os outros de que seu boato original é verdadeiro leva um tempo –2 por acaso.",
