    focus: true,
    summary: "Letras brilhantes se reúnem no ar, transcrevendo a fala do alvo.",
    description: "Letras brilhantes se acumulam no ar, proporcionando uma transcrição da fala do alvo em todos os idiomas que você fala. Durante a duração da magia, quaisquer palavras ditas em voz alta pelo alvo são escritas em letras na frente dele. Ao lançar a magia, você pode escolher se essas letras serão visíveis para todas as criaturas ou apenas para certas criaturas que você especificar. Quaisquer palavras que o alvo pronuncie silenciosamente são escritas de forma semelhante, permitindo que o alvo se comunique silenciosamente ou em áreas onde o som não é transmitido. Isso permite até que o alvo pronuncie os encantamentos necessários para magias em tais áreas, mas apenas se você decidir tornar as letras visíveis para todas as criaturas. Além disso, qualquer uma das habilidades auditivas do alvo pode afetar criaturas mesmo em áreas onde o som não é transmitido, desde que você tenha tornado os glifos visíveis para eles e eles tenham linha de visão para o alvo; neste caso, ganham o traço visual. Você pode descartar a magia.",
