    description: "Você pode enganar criaturas alterando a percepção delas sobre o comportamento de seus aliados. Cada criatura afetada suspeita que seus aliados mudaram de aliança, dependendo do resultado de sua salvaguarda de Vontade. Independentemente dos efeitos das salvaguardas, a criatura fica temporariamente imune a _Quebra-Alcateia_ por 1 hora.\n\n**Sucesso crítico** A criatura não é afetada.\n\n**Sucesso** A criatura se torna hostil a todas as criaturas às quais ainda não era hostil, mesmo aquelas que eram anteriormente aliadas. Não trata ninguém como aliado por 1 minuto. Cada um de seus antigos aliados ao seu alcance deve tentar um salvamento contra _Quebra-Alcateia_.\n\n**Falha** Como sucesso, mas a criatura também fica confusa por 1 rodada.\n\n**Falha crítica** Como sucesso, mas a criatura fica confusa por 1 minuto.",
