    description: "Você acusa o alvo de quebrar sua palavra com você e invoca a ira de seu patrono para reivindicar o que é devido, exigindo que o alvo lhe pague em dinheiro, cumpra um pedido ou renuncie. A exigência não pode ser obviamente autodestrutiva, ou a magia falhará. Se o alvo resistir, você recebe o pagamento da força vital dele. O alvo deve tentar uma salvaguarda de Vontade. Independentemente do resultado do salvamento, o alvo fica temporariamente imune por 1 dia.\n\n**Sucesso crítico** O alvo não é afetado e fica imune ao seu pacto _broker cantrips_ por 1 dia.\n\n**Sucesso** Se o alvo não atender ao seu pedido até o final do próximo turno, ele sofre 3d8 dano persistente do vazio. Se mais tarde cumprir, a magia termina automaticamente.\n\n**Falha** Como sucesso, mas se o alvo não cumprir, é drenado 1 e leva 6d8 dano persistente do vazio.\n\n**Falha crítica** Como sucesso, mas se o alvo não cumprir, é drenado 2 e condenado 1, e leva 6d8 dano persistente do vazio. Mesmo que o alvo complete seus comandos mais tarde, a magia não termina até que todas as condições terminem.\n\n**Altura (9º)** Você pode mirar em até duas criaturas.",
