    description: "Você transcende sua forma física, tornando-se um farol de energia curativa. Seu corpo exala luz brilhante como uma tocha. Você ganha resistência 5 ao dano de precisão e fraqueza 5 ao dano do vazio, e seus Golpe desarmados causam um 1d4 dano de vitalidade extra.\n\n Você pode tocar uma criatura viva com uma ação Interagir para restaurar 6d8 PV a ela, e quando uma criatura toca você com uma ação Interagir você pode permitir que ela ganhe a mesma cura; de qualquer forma, a criatura fica temporariamente imune à cura _life-giving form's_ por 1 minuto. Este é um efeito de cura de vitalidade. Você não pode curar a si mesmo com uma forma vivificante. Uma criatura ferida por dano de vitalidade (como um morto-vivo) que toca você ou causa dano a você com ataques desarmados ou arma corpo a corpo sem alcance, em vez disso, sofre 3d4 dano de vitalidade e não se torna temporariamente imune.\n\n Você pode dispensar esta magia.\n\n**Altura (+1)** O PV restaurado com uma ação Interagir aumenta em 1d8, o dano de vitalidade aumenta em 1 e a resistência e fraqueza aumentam em 1.",
