    actionType: "two",
    focus: true,
    summary: "O corpo se torna fluido.",
    description: "Seu corpo se torna fluido. Escolha se deseja se tornar ar, água ou névoa. A magia ganha a característica ar se você escolher ar ou névoa, e a característica água se você escolher água ou névoa. Você se torna amorfo, assim como sua armadura. Você perde qualquer bônus de item para CA e usa seu bônus de proficiência para defesa sem armadura para determinar seu CA. Você também ganha resistência 10 a dano físico e se torna imune a dano de precisão. Você pode passar por pequenas rachaduras e não precisa respirar. Você não pode lançar magias, ativar itens ou usar ações que possuam a característica ataque ou manipulação, exceto aquelas concedidas por esta magia. Você também ganha os seguintes efeitos com base na sua forma.\n\n- **Ar** Você ganha um Deslocamento de voo de 6 m e fica invisível enquanto está no ar. Você pode criar os efeitos de um _gust of wind_ do seu espaço como uma atividade de 2 ações, que possui a característica manipular.\n- **Névoa** Você ganha um Deslocamento de voo de 6 m, e fica difícil ver através de você. Qualquer criatura em um lado do seu espaço que seja alvo de uma criatura no lado oposto fica oculta à criatura alvo.\n- **Água** Você ganha um Deslocamento de natação de 6 m e fica invisível enquanto estiver na água. Você pode se carregar eletricamente executando 1 ação, que possui a característica manipular. Se fizer isso, você não ficará mais invisível na água devido à eletricidade que indica sua localização, mas qualquer criatura que fizer um Golpe corpo a corpo contra você sofre 1d6 dano de eletricidade.\n\n**Altura (+2)** A resistência aumenta em 5, e o dano de eletricidade da forma de água carregada aumenta em 1.",
