    focus: true,
    summary: "Aprimora uma criatura invocada com o poder dos elementos.",
    description: "Você aprimora uma criatura invocada com o poder dos elementos. Se sua próxima ação for lançar _Conjurar Animal_ ou _summon plant ou fungus_, escolha ar, terra, fogo, metal, água ou madeira; a criatura que você invoca ganha as habilidades correspondentes.\n\n- **Ar** A criatura ganha um Deslocamento de voo de 18 m.\n- **Terra** A criatura ganha um Deslocamento de escavação de 6 m, reduz seu Deslocamento terrestre em 3 m (mínimo 1,5 m) e ganha resistência 5 a dano físico.\n- **Fogo** Os Golpes da criatura causam 1d6 dano de fogo extra, e ela ganha resistência 10 ao fogo e fraqueza 5 ao frio e à água.\n- **Metal** Os Golpes da criatura causam 1d6 dano de eletricidade extra, e ela ganha resistência 5 à eletricidade.\n- **Água** A criatura ganha um Deslocamento de natação de 18 m, pode gastar 1 ação após um Golpe corpo a corpo para tentar um Empurrar (ignorando o ataque de ataques múltiplos) e ganha resistência 5 ao fogo.\n- **Madeira** A criatura ganha Deslocamento de escalada de 9 m e resistência 2 a concussão e dano perfurante.",
