    summary: "Invoca uma ponte de luar radiante e cintilante.",
    description: "Você invoca uma ponte de luar radiante e cintilante. O vão de 3 m de largura deve começar no solo em um ponto dentro do alcance e se estender como um plano horizontal, em linha reta ou em qualquer ângulo de até 45 graus para cima ou para baixo, por até 36 m. Esta ponte tem CA 10, Dureza 30 e 60 PV, e é imune a todos os danos (exceto força, espírito e dano de Golpes com a runa de propriedade _ghost touch_). Você e seus aliados podem cruzar a ponte normalmente, mas outras criaturas simplesmente passam por ela se tentarem fazê-lo. A ponte bloqueia ataques físicos, etéreos e incorpóreos de atravessá-la, sejam de cima ou de baixo. Você pode descartar a magia.\n\n**Altura (+1)** O comprimento da ponte aumenta em 6 m, seu PV aumenta em 20, e você pode aumentar a largura do vão em até 1,5 m adicionais.",
