    focus: true,
    summary: "Tenta tomar o controle de um morto-vivo ou fazê-lo reconhecê-lo como mestre.",
    description: "Você tenta tomar o controle de um alvo morto-vivo ou forçá-lo a reconhecê-lo como seu mestre. Se o alvo for controlado por outra criatura, esse controlador tenta uma salvaguarda de Vontade para manter o controle; caso contrário, o alvo deverá tentar uma salvaguarda de Vontade.\n\n**Sucesso crítico** O alvo não é afetado.\n\n**Sucesso** O alvo fica atordoado 1 e confuso por 1 rodada enquanto luta contra seus comandos.\n\n**Falha** O alvo passa a ser controlado por você e segue suas ordens. Ele (ou a criatura que o controlava anteriormente) pode tentar uma nova salvaguarda de Vontade no final de cada um de seus turnos; caso obtenha sucesso, a magia termina e a criatura fica atordoada 1 e confusa por 1 rodada. Se você emitir uma ordem obviamente autodestrutiva, o alvo não agirá até que você emita uma nova ordem.\n\n**Falha crítica** Como falha, mas o alvo (ou a criatura que o controlava anteriormente) recebe um novo salvamento somente se você der a ele uma nova ordem que seja contra sua natureza.",
