    summary: "Profere um segredo poderoso em desacordo com a natureza fundamental dos alvos.",
    description: "Você revela um segredo poderoso que está em desacordo com a natureza fundamental das criaturas alvo. Escolha uma resistência ou fraqueza específica com um valor numérico que você acredita que um ou mais dos alvos possuem devido ao Recordar Conhecimento ou experiência anterior com os alvos, como resistência ao fogo ou fraqueza à prata. Se a informação estiver incorreta para um determinado alvo, a magia não terá efeito naquele alvo. Os alvos afetados devem tentar uma salvaguarda de Vontade.\n\n**Sucesso crítico** A criatura não é afetada.\n\n**Sucesso** A criatura sofre 1 dano que corresponde ao tipo ou característica de fraqueza que você escolheu (desencadeando assim a fraqueza da criatura) se você escolheu uma fraqueza, ou perde sua resistência até o fim do seu próximo turno se você escolheu uma resistência.\n\n**Falha** Com sucesso, a criatura fica amedrontada 1 a partir da revelação de seu terrível segredo.\n\n**Falha crítica** Como falha, exceto que a criatura está amedrontada 3.",
