    provenance: { type: 'official' },
    actionType: "two",
    focus: true,
    summary: "A magia ganha vida ao redor, alimentando-se do poder bruto que você irradia.",
    description: "A magia ganha vida ao seu redor, alimentando-se do poder bruto que você irradia. Escolha uma das seguintes habilidades para afetar as criaturas em sua aura. Você pode escolher um efeito diferente, encerrando o anterior, sustentando a magia. Você pode descartar a aura.\n **Interferência** O excesso de magia ao seu redor cria uma estática mental. Todas as salvaguardas contra efeitos mentais ganham +2 de bônus de circunstância. **Mana Well** Você se torna uma fonte de pura magia que permite que magias sejam lançados com mais liberdade. Criaturas aliadas que normalmente seriam obrigadas a tentar um teste simples para Conjurar uma Magia (como na condição aturdido) são automaticamente bem-sucedidas. **Resistência a Overpower** A magia crescente penetra na maioria das defesas. Sempre que uma magia afeta uma criatura dentro da aura, aquela magia ignora uma quantidade de resistência da criatura igual ao seu nível. Isto se aplica a todos os danos que a magia causa, incluindo dano persistente e dano causado por um efeito contínuo da magia. Isso não faz com que a magia ignore imunidades. **Ward Stray** energia mágica difunde magias prejudiciais. Sempre que uma magia afeta uma criatura dentro da aura, o dano causado pela magia é reduzido em uma quantidade igual ao seu nível. Isto se aplica a todos os danos que a magia causa, incluindo dano persistente e dano causado por um efeito contínuo da magia.",
    duration: "1 minuto",
    area: "emanação de 3 m",
