    description: "Você lança a mente de uma criatura de volta no tempo, forçando-a a seguir outros caminhos e fazer outras escolhas, experimentando inúmeras vidas alternativas em um instante. A criatura fica sobrecarregada de arrependimento por caminhos não percorridos, vidas não vividas e tempos não realizados. A criatura sofre 6d6 dano mental e deve tentar uma salvaguarda de Vontade. Após o efeito ser resolvido, o alvo fica temporariamente imune por 1 dia.\n\n**Sucesso crítico** A criatura não é afetada.\n\n**Sucesso** A criatura sofre metade do dano e fica aturdido 2 por 1 rodada.\n\n**Falha** A criatura sofre dano total e fica aturdido 2 por 1 minuto. Enquanto afetada, a criatura deve tentar outro salvamento no início do seu turno; em caso de falha, ele fica lento 1 naquele turno enquanto soluça incontrolavelmente.\n\n**Falha crítica** A criatura sofre o dobro de dano e por 1 minuto fica aturdido 4 e lento 1 enquanto soluça incontrolavelmente.\n\n**Altura (+1)** O dano mental aumenta em 1d6.",
