    description: "O solo dentro da área se transforma em uma massa de espinhos perigosos que atacam e impedem seus inimigos. Ao lançar o Magia e na primeira vez que você Sustentá-lo em cada turno nas rodadas subsequentes, selecione um dos seguintes efeitos para ocorrer na área.\n **Ensnare** As sarças se aglomeram em torno de seus inimigos, tentando mantê-los no lugar. Um inimigo dentro da área (ou voando no máximo 6 m acima da área) deve tentar uma salvaguarda de Reflexos. Falha: leva –3 m de coincidência de circunstância a todas as Velocidades por 1 rodada, e em uma falha crítica, fica imóvel por 1 rodada a menos que Escape. ** Impedir ** Os arbustos se retorcem e se contorcem, tornando todo o terreno difícil. **Parede** Um _wall of thorns_ aparece na área, durando 1 rodada. A parede é um terreno maior difícil em vez de terreno difícil. Além disso, 1 vez por rodada você pode direcionar as sarças para empalar qualquer alvo na área (ou voar até 6 m acima da área) que você possa ver usando uma ação 1, que possui as características concentrar e manipular. Faça uma rolagem de ataque de magia. Sucesso: o alvo sofre 10d6 dano perfurante e sofre –10 pés de desvio de ocasião para todas as Velocidades por 1 rodada; em caso de sucesso crítico, o alvo fica imóvel por 1 rodada, a menos que escape.",
    duration: "sustentada até 1 minuto",
    area: "ground within a emanação de 30 m",
    aonUrl: "https://2e.aonprd.com/Spells.aspx?ID=1857",
