    focus: true,
    summary: "Começa a transformar o alvo em osso.",
    description: "Você transforma um escravo em finas partículas de poeira que invadem o corpo de uma criatura e começa a transformar seu corpo em uma estátua feita de puro osso aprimorado. Destrua um servo dentro do alcance e escolha uma criatura viva ou morta-viva num raio de 18 m de onde o servo estava. A criatura começa a se solidificar em osso puro dependendo de sua segurança de Fortitude. Criaturas já feitas exclusivamente de osso, como esqueletos, são imunes a esta magia. Uma criatura incorpórea lenta por esta magia perde o traço incorpóreo e todas as resistências associadas durante a duração da magia.\n\n**Sucesso crítico** A criatura não é afetada.\n\n**Sucesso** A criatura é lenta 1 e tem fraqueza 5 a concussão por 1 rodada.\n\n**Falha** A criatura é lenta 1 e tem fraqueza 10 para concussão enquanto for lenta. A criatura deve tentar uma salvaguarda de Fortitude adicional no final de cada um de seus turnos; este salvamento contínuo tem o traço de incapacitação. Em caso de falha no teste, a condição lento aumenta em 1 (ou 2 em caso de falha crítica) à medida que os crescimentos ósseos se espalham pelo corpo da criatura. Um teste bem-sucedido reduz a condição lenta em 1. Quando uma criatura se torna totalmente incapaz de agir devido à condição lenta devido à calcificação, a magia termina, deixando a criatura petrificada permanentemente, tornando-se uma estátua óssea. A magia também termina se a condição lenta for removida, o que faz com que o osso se quebre inofensivamente.\n\n**Falha crítica** Como falha, mas o alvo é inicialmente lento 2.",
