    focus: true,
    summary: "O corpo vira uma bola de magia pura, explode para fora e se reforma numa esfera.",
    description: "Seu corpo é temporariamente convertido em uma bola de pura magia, explodindo rapidamente e se transformando em uma esfera brilhante, após a qual você eventualmente recupera sua forma normal. Todas as criaturas e objetos da emanação recebem 16d6 dano de força (Fortitude básica salvaguardas). As criaturas que falham também são empurradas 3 m diretamente para longe de você; criaturas que não conseguem completar este movimento forçado são derrubadas (mas criaturas que reduzem este movimento, como com uma habilidade ou talento, não caem). Você se torna magia não filtrada; você ganha o traço incorpóreo, é imune a doenças, veneno e dano de precisão, e ganha resistência a todos os danos iguais ao seu nível (exceto dano de força, dano espiritual e dano de Golpes com a runa de propriedade toque fantasma), com o dobro da resistência contra danos não mágicos. Enquanto incorpóreo, você não pode Golpe, Conjurar uma Magia ou realizar qualquer ação com o traço manipular. Qualquer criatura que termine seu turno adjacente a você enquanto você estiver nesse estado sofre 6d6 dano de força. Você permanece como pura magia até Dispensar sua nova forma, retornando ao seu estado normal com PV máximo.",
