    description: "Extraindo de poços profundos de poder espiritual, você assume uma forma especial de qi. Na sua forma de qi, seu cabelo, penas, pele ou escamas mudam de cor e começam a brilhar. Nesta forma, você ganha um Deslocamento de voo igual ao seu Deslocamento terrestre. Escolha força, espírito, vitalidade ou dano do vazio. Todos os seus Golpes causam 1d6 de dano adicional do tipo escolhido. Todo o seu corpo também é cercado por uma coroa brilhante da mesma cor do seu qi interno; este é um efeito de luz. Sua corona é uma aura em uma emanação de 1,5 m que causa 2d6 de dano do tipo escolhido às criaturas que iniciam seu turno dentro da emanação. Se a emanação se sobrepõe a um efeito de escuridão, o brilho da coroa tenta contrapor a escuridão. Independentemente do resultado, a corona não pode tentar contrapor esse efeito novamente por 1 dia. Você pode Sustentar para alargar sua corona para se tornar uma emanação de 9 m ou retornar a corona para uma emanação de 1,5 m.\n\n Em sua forma de qi, suas emoções vêm à tona e é difícil moderar seus ataques. Suas armas e ataques desarmados perdem a característica não letal. Você recebe -2 de status para testes de resistência contra efeitos emocionais, mas ganha +2 de bônus de status para testes de resistência contra todos os outros efeitos mentais.",
