    description: "Você lança um escravo de até 9 m no cadáver de um inimigo que está morto há não mais que 1 minuto, destruindo o escravo em um esforço para chamar o cadáver para lutar. Tente um teste de Undead Lore contra a CD padrão do nível do inimigo que você está tentando reanimar. Você pode reanimar apenas cadáveres de criaturas que já foram vivas ou mortas-vivas.\n\n**Sucesso** O inimigo reanima em um espaço desocupado adjacente ao seu cadáver. Está sob seu controle e possui a característica de lacaio. Possui o mesmo modificador de ataque, CA, modificadores de salvaguardas, Percepção e modificadores de habilidade, mas tem apenas 100 PV e não possui todas as habilidades especiais, incluindo imunidades, resistências e fraquezas. Não possui itens mágicos, exceto as armas e armaduras que usou antes de morrer. Seus Golpes causam o dano normal, mas não aplicam efeitos adicionais, pois a criatura não possui habilidades especiais. O inimigo reanimado é instável e decai rapidamente. A cada turno após realizar suas ações, ele perde 15 PV. Ele não pode recuperar o PV perdido de forma alguma. A criatura reanimada dura 1 minuto ou até ser reduzida a 0 PV.\n\n**Falha** Como sucesso, mas o inimigo reanimado causa metade do dano com seus Golpes e perde 50 PV a cada turno em vez de 15.\n\n**Falha crítica** Você cria um escravo no espaço do cadáver, mas não gasta os Pontos de Foco para lançar esta magia.",
